package com.ynotlabs.cathopedia.speech

// GENERATED by tools/audio/generate_prayer_audio.py --fixture. Do not edit.
// Real prayers with the part keys the audio generator computed for them.
internal val PrayerAudioParityCases: List<ParityCase> = listOf(
    ParityCase("en", "Our Father", "Our Father, Who art in heaven,\nHallowed be Thy Name.\nThy Kingdom come.\nThy Will be done, on earth as it is in Heaven.\nGive us this day our daily bread.\nAnd forgive us our trespasses,\nas we forgive those who trespass against us.\nAnd lead us not into temptation,\nbut deliver us from evil.\nAmen.", listOf("56c99b3276108b08", "d976a948364e566d")),
    ParityCase("la", "Pater Noster", "Pater noster, qui es in caelis,\nsanctificetur nomen tuum.\nAdveniat regnum tuum.\nFiat voluntas tua, sicut in caelo et in terra.\nPanem nostrum quotidianum da nobis hodie,\net dimitte nobis debita nostra\nsicut et nos dimittimus debitoribus nostris.\nEt ne nos inducas in tentationem,\nsed libera nos a malo.\nAmen.", listOf("4579c656634dbf7d", "33953665b785bb52")),
    ParityCase("fr", "Notre Père", "Notre Père, qui es aux cieux,\nque ton nom soit sanctifié,\nque ton règne vienne,\nque ta volonté soit faite sur la terre comme au ciel.\nDonne-nous aujourd'hui notre pain de ce jour.\nRemets-nous nos dettes,\ncomme nous-mêmes nous remettons leurs dettes à nos débiteurs.\nEt ne nous laisse pas entrer en tentation,\nmais délivre-nous du Mal.", listOf("f08ce3b6738b9a21", "9b8420343c82d3cd")),
    ParityCase("it", "Padre Nostro", "Padre nostro, che sei nei cieli,\nsia santificato il tuo nome,\nvenga il tuo regno,\nsia fatta la tua volontà,\ncome in cielo così in terra.\nDacci oggi il nostro pane quotidiano,\ne rimetti a noi i nostri debiti\ncome anche noi li rimettiamo ai nostri debitori,\ne non abbandonarci alla tentazione,\nma liberaci dal male.\nAmen.", listOf("7f6e76e023c56039", "56d87b0f2c9b3687")),
    ParityCase("es", "Padrenuestro", "Padre nuestro, que estás en el cielo,\nsantificado sea tu Nombre;\nvenga a nosotros tu Reino;\nhágase tu voluntad en la tierra como en el cielo.\nDanos hoy nuestro pan de cada día;\nperdona nuestras ofensas,\ncomo también nosotros perdonamos a los que nos ofenden;\nno nos dejes caer en la tentación,\ny líbranos del mal.\nAmén.", listOf("c836fe9bda61e611", "1116a510e8f9e720")),
    ParityCase("pt", "Pai-Nosso", "Pai nosso que estais nos céus,\nsantificado seja o vosso nome;\nvenha a nós o vosso reino;\nseja feita a vossa vontade, assim na terra como no céu.\nO pão nosso de cada dia nos dai hoje;\nperdoai-nos as nossas ofensas,\nassim como nós perdoamos a quem nos tem ofendido;\ne não nos deixeis cair em tentação,\nmas livrai-nos do mal.\nAmém.", listOf("7523836c72f8a78e", "fe34d5cbf38b19e9")),
    ParityCase("de", "Vaterunser", "Vater unser im Himmel,\ngeheiligt werde dein Name.\nDein Reich komme.\nDein Wille geschehe, wie im Himmel, so auf der Erde.\nUnser tägliches Brot gib uns heute.\nUnd vergib uns unsere Schuld,\nwie auch wir vergeben unsern Schuldigern.\nUnd führe uns nicht in Versuchung,\nsondern erlöse uns von dem Bösen.\nAmen.", listOf("ee88029f7fecf90b", "34c4bcc3760a34ad")),
    ParityCase("nl", "Onze Vader", "Onze Vader, die in de hemel zijt,\nuw naam worde geheiligd,\nuw rijk kome,\nuw wil geschiede op aarde zoals in de hemel.\nGeef ons heden ons dagelijks brood,\nen vergeef ons onze schulden,\nzoals ook wij aan anderen hun schulden vergeven,\nen leid ons niet in bekoring,\nmaar verlos ons van het kwade.\nAmen.", listOf("2aab25b28e201f03", "2224652a20db4e82")),
    ParityCase("pl", "Ojcze nasz", "Ojcze nasz, któryś jest w niebie,\nświęć się imię Twoje,\nprzyjdź królestwo Twoje,\nbądź wola Twoja jako w niebie, tak i na ziemi.\nChleba naszego powszedniego daj nam dzisiaj\ni odpuść nam nasze winy,\njako i my odpuszczamy naszym winowajcom,\ni nie wódź nas na pokuszenie,\nale nas zbaw ode złego.\nAmen.", listOf("c048961a688f8350", "7c7a9ffe5a67c5ed")),
    ParityCase("ta", "விண்ணுலகில் இருக்கிற எங்கள் தந்தையே", "விண்ணுலகில் இருக்கிற எங்கள் தந்தையே,\nஉமது பெயர் தூயது எனப் போற்றப்பெறுக!\nஉமது ஆட்சி வருக!\nஉமது திருவுளம் விண்ணுலகில் நிறைவேறுவது போல மண்ணுலகிலும் நிறைவேறுக!\nஎங்கள் அன்றாட உணவை இன்று எங்களுக்குத் தாரும்.\nஎங்களுக்கு எதிராகக் குற்றம் செய்வோரை நாங்கள் மன்னிப்பது போல\nஎங்கள் குற்றங்களை மன்னியும்.\nஎங்களைச் சோதனைக்கு உட்படுத்தாதேயும்;\nதீமையிலிருந்து எங்களை விடுவித்தருளும்.\nஆமென்.", listOf("7a35280de8b29ade", "916009d641e7b88d")),
    ParityCase("en", "The Angelus", "> V. The Angel of the Lord declared to Mary,\n> R. And she conceived of the Holy Spirit.\n\nHail Mary, full of grace, the Lord is with thee;\nblessed art thou among women,\nand blessed is the fruit of thy womb, Jesus.\nHoly Mary, Mother of God, pray for us sinners,\nnow and at the hour of our death. Amen.\n\n> V. Behold the handmaid of the Lord.\n> R. Be it done unto me according to thy word.\n\nHail Mary…\n\n> V. And the Word was made flesh.\n> R. And dwelt among us.\n\nHail Mary…\n\n> V. Pray for us, O holy Mother of God.\n> R. That we may be made worthy of the promises of Christ.\n\nLet us pray. Pour forth, we beseech Thee, O Lord,\nThy grace into our hearts;\nthat we, to whom the Incarnation of Christ Thy Son\nwas made known by the message of an angel,\nmay by His Passion and Cross be brought to the glory of His Resurrection.\nThrough the same Christ our Lord. Amen.", listOf("0c8e16160f18b956", "91bee0086d4e0883", "276dd8eea94135ab", "6c79995ac7d2166c", "fb3a543040fff1ef", "da742306fbb0aae1", "fb3a543040fff1ef", "cc9f56d634ed99ef", "b8889075b1bcb860")),
    ParityCase("la", "Angelus Domini", "> V. Angelus Domini nuntiavit Mariae.\n> R. Et concepit de Spiritu Sancto.\n\nAve Maria, gratia plena; Dominus tecum:\nbenedicta tu in mulieribus, et benedictus fructus ventris tui Iesus.\nSancta Maria, Mater Dei, ora pro nobis peccatoribus,\nnunc et in hora mortis nostrae. Amen.\n\n> V. Ecce ancilla Domini.\n> R. Fiat mihi secundum verbum tuum.\n\nAve Maria…\n\n> V. Et Verbum caro factum est.\n> R. Et habitavit in nobis.\n\nAve Maria…\n\n> V. Ora pro nobis, sancta Dei Genetrix.\n> R. Ut digni efficiamur promissionibus Christi.\n\nOremus. Gratiam tuam, quaesumus, Domine, mentibus nostris infunde;\nut qui, Angelo nuntiante, Christi Filii tui incarnationem cognovimus,\nper passionem eius et crucem ad resurrectionis gloriam perducamur.\nPer eumdem Christum Dominum nostrum. R. Amen.", listOf("03e798e0f0837169", "47700261c82dc36b", "23e88a25e3e57aff", "64f0ef42afcc4ed7", "52756876db07bdf0", "b0e3b2d340c6a056", "52756876db07bdf0", "12d8c1e441016cb5", "ad8adec5a600d6ba")),
    ParityCase("fr", "L'Angélus", "> V. L'ange du Seigneur porta l'annonce à Marie.\n> R. Et elle conçut du Saint-Esprit.\n\nJe vous salue Marie, pleine de grâce,\nle Seigneur est avec vous,\nvous êtes bénie entre toutes les femmes,\net Jésus, le fruit de vos entrailles, est béni.\nSainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs,\nmaintenant et à l'heure de notre mort. Amen.\n\n> V. Voici la servante du Seigneur.\n> R. Qu'il me soit fait selon votre parole.\n\nJe vous salue Marie…\n\n> V. Et le Verbe s'est fait chair.\n> R. Et il a habité parmi nous.\n\nJe vous salue Marie…\n\n> V. Priez pour nous, sainte Mère de Dieu.\n> R. Afin que nous devenions dignes des promesses du Christ.\n\nPrions le Seigneur.\nQue ta grâce, Seigneur notre Père, se répande en nos cœurs ;\npar le message de l'ange, tu nous as fait connaître l'incarnation de ton Fils bien-aimé ;\nconduis-nous, par sa passion et par sa croix, jusqu'à la gloire de la Résurrection.\nPar Jésus, le Christ, notre Seigneur. Amen.", listOf("0ef353f79aa88510", "aff9030d86e76b86", "64b4eaae62dfcc36", "fc16a1572ce553b0", "f5fd8dce6316d165", "d064f2a749493077", "f5fd8dce6316d165", "c3045f6c513febb1", "32904bfabbb9d923")),
    ParityCase("it", "Angelus", "> V. L'Angelo del Signore portò l'annunzio a Maria.\n> R. Ed ella concepì per opera dello Spirito Santo.\n\nAve, o Maria, piena di grazia, il Signore è con te.\nTu sei benedetta fra le donne\ne benedetto è il frutto del tuo seno, Gesù.\nSanta Maria, Madre di Dio,\nprega per noi peccatori,\nadesso e nell'ora della nostra morte. Amen.\n\n> V. Eccomi, sono la serva del Signore.\n> R. Si compia in me la tua parola.\n\nAve, o Maria…\n\n> V. E il Verbo si fece carne.\n> R. E venne ad abitare in mezzo a noi.\n\nAve, o Maria…\n\n> V. Prega per noi, santa Madre di Dio.\n> R. Perché siamo resi degni delle promesse di Cristo.\n\nPreghiamo. Infondi nel nostro spirito la tua grazia, o Padre;\ntu, che nell'annunzio dell'angelo\nci hai rivelato l'incarnazione del tuo Figlio,\nper la sua passione e la sua croce\nguidaci alla gloria della risurrezione.\nPer Cristo nostro Signore. Amen.", listOf("482fa25e1201e0a3", "8fe9553966f73ca4", "da6d441bed6a2231", "d9fe50a482ca9ac3", "823a40c9b1d963b1", "e79a91756572c1c7", "823a40c9b1d963b1", "8565bacc4295bcaf", "5e4fe3ee0ccb9675")),
    ParityCase("es", "El Ángelus", "> V. El ángel del Señor anunció a María.\n> R. Y concibió por obra y gracia del Espíritu Santo.\n\nDios te salve, María, llena eres de gracia; el Señor es contigo.\nBendita tú eres entre todas las mujeres,\ny bendito es el fruto de tu vientre, Jesús.\nSanta María, Madre de Dios, ruega por nosotros, pecadores,\nahora y en la hora de nuestra muerte. Amén.\n\n> V. He aquí la esclava del Señor.\n> R. Hágase en mí según tu palabra.\n\nDios te salve, María…\n\n> V. Y el Verbo de Dios se hizo carne.\n> R. Y habitó entre nosotros.\n\nDios te salve, María…\n\n> V. Ruega por nosotros, Santa Madre de Dios.\n> R. Para que seamos dignos de alcanzar las promesas de Jesucristo.\n\nOremos. Infunde, Señor, tu gracia en nuestras almas,\npara que, los que hemos conocido, por el anuncio del Ángel,\nla Encarnación de tu Hijo Jesucristo,\nlleguemos por los méritos de su Pasión y su Cruz\na la gloria de la Resurrección.\nPor Jesucristo nuestro Señor. Amén.", listOf("5ff226f9577e3516", "c15fc08bfe9766eb", "24a3f2dbbc0ffe1d", "cb7f639410769d43", "8afe4b80321dcbbb", "3d2afbd3d111f4aa", "8afe4b80321dcbbb", "2c8810100b1b53ff", "a9bb68ab134ec9cf")),
    ParityCase("pt", "O Ângelus", "> V. O Anjo do Senhor anunciou a Maria.\n> R. E ela concebeu do Espírito Santo.\n\nAve Maria, cheia de graça, o Senhor é convosco;\nbendita sois vós entre as mulheres,\ne bendito é o fruto do vosso ventre, Jesus.\nSanta Maria, Mãe de Deus, rogai por nós, pecadores,\nagora e na hora de nossa morte. Amém.\n\n> V. Eis aqui a serva do Senhor.\n> R. Faça-se em mim segundo a vossa palavra.\n\nAve Maria…\n\n> V. E o Verbo se fez carne.\n> R. E habitou entre nós.\n\nAve Maria…\n\n> V. Rogai por nós, santa Mãe de Deus.\n> R. Para que sejamos dignos das promessas de Cristo.\n\nOremos. Infundi, Senhor, como vos pedimos, a vossa graça em nossas almas,\npara que nós, que pela anunciação do Anjo\nconhecemos a encarnação de Cristo, vosso Filho,\npor sua paixão e cruz\nsejamos conduzidos à glória da ressurreição.\nPelo mesmo Cristo, Senhor nosso. Amém.", listOf("62edcb336c6dc029", "3bd49ec191897086", "618f9e111208c6b7", "08688f19c58f1147", "0785605460dca569", "c985b791792dcfd9", "0785605460dca569", "38f1983335cf7401", "a69d5aa174d0838a")),
    ParityCase("de", "Der Engel des Herrn", "> V. Der Engel des Herrn brachte Maria die Botschaft.\n> R. Und sie empfing vom Heiligen Geist.\n\nGegrüßet seist du, Maria, voll der Gnade, der Herr ist mit dir.\nDu bist gebenedeit unter den Frauen,\nund gebenedeit ist die Frucht deines Leibes, Jesus.\nHeilige Maria, Mutter Gottes, bitte für uns Sünder\njetzt und in der Stunde unseres Todes. Amen.\n\n> V. Maria sprach: Siehe, ich bin die Magd des Herrn.\n> R. Mir geschehe nach deinem Wort.\n\nGegrüßet seist du, Maria …\n\n> V. Und das Wort ist Fleisch geworden.\n> R. Und hat unter uns gewohnt.\n\nGegrüßet seist du, Maria …\n\n> V. Bitte für uns, heilige Gottesmutter.\n> R. Dass wir würdig werden der Verheißungen Christi.\n\nLasset uns beten. Allmächtiger Gott, gieße deine Gnade in unsere Herzen ein.\nDurch die Botschaft des Engels haben wir die Menschwerdung Christi, deines Sohnes, erkannt.\nFühre uns durch sein Leiden und Kreuz\nzur Herrlichkeit der Auferstehung.\nDarum bitten wir durch Christus, unsern Herrn. Amen.", listOf("3b2882371df56295", "5d797ea592428a45", "1b1af92d664ed194", "3e16884530685dd8", "b08a2d18dbbc0cf6", "9f89f50e12089154", "b08a2d18dbbc0cf6", "67e96df40c5a4fdc", "919860cbc8385937")),
    ParityCase("nl", "De engel des Heren", "> V. De engel des Heren heeft aan Maria geboodschapt.\n> R. En zij heeft ontvangen van de heilige Geest.\n\nWees gegroet, Maria, vol van genade, de Heer is met u.\nGij zijt de gezegende onder de vrouwen,\nen gezegend is Jezus, de vrucht van uw schoot.\nHeilige Maria, Moeder van God, bid voor ons, zondaars,\nnu en in het uur van onze dood. Amen.\n\n> V. Zie de dienstmaagd des Heren.\n> R. Mij geschiede naar uw woord.\n\nWees gegroet, Maria…\n\n> V. En het Woord is vlees geworden.\n> R. En het heeft onder ons gewoond.\n\nWees gegroet, Maria…\n\n> V. Bid voor ons, heilige Moeder van God.\n> R. Opdat wij de beloften van Christus waardig worden.\n\nLaat ons bidden. Heer, wij bidden U, stort uw genade in onze harten;\nen zoals wij door de boodschap van de engel\nde menswording van Christus, uw Zoon, hebben leren kennen,\nlaat ons zo door zijn lijden en kruis\ntot de glorie van de verrijzenis gebracht worden.\nDoor dezelfde Christus onze Heer. Amen.", listOf("bfb10103e0381dd1", "7a72beccecf490cd", "0a9d67561d74dec3", "19001ae931ff0dc9", "58298ee43b0cf07e", "fbe0ea4f3ae702c5", "58298ee43b0cf07e", "b17fd228928bcb7e", "cbd612281189a242")),
    ParityCase("pl", "Anioł Pański", "> V. Anioł Pański zwiastował Pannie Maryi.\n> R. I poczęła z Ducha Świętego.\n\nZdrowaś Maryjo, łaski pełna, Pan z Tobą,\nbłogosławionaś Ty między niewiastami\ni błogosławiony owoc żywota Twojego, Jezus.\nŚwięta Maryjo, Matko Boża, módl się za nami grzesznymi\nteraz i w godzinę śmierci naszej. Amen.\n\n> V. Oto ja służebnica Pańska.\n> R. Niech mi się stanie według słowa twego.\n\nZdrowaś Maryjo…\n\n> V. A Słowo ciałem się stało.\n> R. I zamieszkało między nami.\n\nZdrowaś Maryjo…\n\n> V. Módl się za nami, święta Boża Rodzicielko.\n> R. Abyśmy się stali godnymi obietnic Chrystusowych.\n\nMódlmy się. Łaskę Twoją, prosimy Cię, Panie, racz wlać w serca nasze,\nabyśmy, którzy za zwiastowaniem anielskim\nwcielenie Chrystusa, Syna Twego, poznali,\nprzez mękę Jego i krzyż\ndo chwały zmartwychwstania byli doprowadzeni.\nPrzez tegoż Chrystusa, Pana naszego. Amen.", listOf("00ae094a7b43f57e", "68c605d4fd2049ab", "158084bd7c466212", "f387a8483487bb33", "58402267772ecf90", "df51504447bdeb15", "58402267772ecf90", "e9215bd59f7f128a", "ed6d817380336e06")),
    ParityCase("ta", "மூவேளைச் செபம்", "> V. ஆண்டவருடைய தூதர் மரியாவுக்கு அறிவித்தார்.\n> R. அவர் தூய ஆவியாரால் கருத்தாங்கினார்.\n\nஅருள் நிறைந்த மரியே வாழ்க! ஆண்டவர் உம்முடனே.\nபெண்களுக்குள் ஆசீர்வதிக்கப்பட்டவர் நீரே;\nஉம்முடைய திருவயிற்றின் கனியாகிய இயேசுவும் ஆசீர்வதிக்கப்பட்டவரே.\nபுனித மரியாவே, இறைவனின் தாயே, பாவிகளாய் இருக்கிற எங்களுக்காக\nஇப்பொழுதும் எங்கள் இறப்பின் வேளையிலும் வேண்டிக்கொள்ளும். ஆமென்.\n\n> V. இதோ ஆண்டவருடைய அடிமை.\n> R. உமது சொற்படியே எனக்கு நிகழட்டும்.\n\nஅருள் நிறைந்த மரியே…\n\n> V. வார்த்தை மனுவுருவானார்.\n> R. நம்மிடையே குடிகொண்டார்.\n\nஅருள் நிறைந்த மரியே…\n\n> V. இறைவனின் புனித அன்னையே, எங்களுக்காக வேண்டிக்கொள்ளும்.\n> R. கிறிஸ்துவின் வாக்குறுதிகளுக்கு நாங்கள் தகுதியுள்ளவர்களாகும்படியாக.\n\nமன்றாடுவோமாக. ஆண்டவரே, உமது அருளை எங்கள் உள்ளங்களில் பொழிந்தருளும்;\nவானதூதரின் அறிவிப்பால் உம் திருமகன் கிறிஸ்துவின்\nமனுவுருவாதலை அறிந்த நாங்கள்,\nஅவருடைய பாடுகளாலும் சிலுவையாலும்\nஉயிர்ப்பின் மாட்சிக்கு வந்து சேர அருள்புரியும்.\nஎங்கள் ஆண்டவராகிய அதே கிறிஸ்து வழியாக. ஆமென்.", listOf("ab11dd7737cd5791", "9b14903094cc42ad", "e06c7a3c4cc83c25", "e00242872af62a7e", "fae56b7822f02c79", "97654c3fecde6abb", "fae56b7822f02c79", "2cf0e810939ab367", "767bfe73a6c998c3")),
    ParityCase("en", "Rosary of the Seven Sorrows", "## How to pray\n\nBegin with an **Act of Contrition**. For each sorrow, announce the mystery, pause to meditate, then pray **one Our Father and seven Hail Marys**.\n\n## 1. The Prophecy of Simeon\n\n**Luke 2:25–35**\n\nSimeon receives the Child Jesus in the Temple and tells Mary that a sword will pierce her own soul. Mary accepts that loving her Son will also mean sharing in his suffering.\n\n## 2. The Flight into Egypt\n\n**Matthew 2:13–15**\n\nWarned of Herod’s danger, Mary and Joseph flee with the infant Jesus. Mary carries the Son of God into exile, trusting the Father amid fear and uncertainty.\n\n## 3. The Loss of the Child Jesus in the Temple\n\n**Luke 2:41–50**\n\nAfter three anxious days, Mary and Joseph find Jesus among the teachers in the Temple. Mary treasures his words even when the path of his mission is difficult to understand.\n\n## 4. Mary Meets Jesus Carrying the Cross\n\n**Traditional devotion; see Luke 23:27–31**\n\nOn the road to Calvary, Mother and Son meet in silent compassion. Mary cannot remove the Cross, but her faithful presence accompanies Jesus in his suffering.\n\n## 5. Mary Stands Beneath the Cross\n\n**John 19:25–30**\n\nMary remains beside Jesus at Calvary. From the Cross, Christ entrusts her to the beloved disciple and gives her as a mother to his disciples.\n\n## 6. Mary Receives the Body of Jesus\n\n**Traditional devotion; see John 19:31–37**\n\nThe body of Jesus is taken down from the Cross and placed in his mother’s arms. Mary holds the Son she once cradled at Bethlehem and offers her grief to God.\n\n## 7. The Burial of Jesus\n\n**John 19:38–42**\n\nMary accompanies Jesus to the tomb and remains faithful when every human hope appears extinguished. Her sorrow waits in the silence before Easter.\n\n## Concluding prayers\n\nPray **three Hail Marys** in honor of Our Lady’s tears, then one **Our Father**, one **Hail Mary**, and one **Glory Be** for the intentions of the Holy Father.\n\nRepeat three times:\n\n> Virgin most sorrowful, pray for us.", listOf("e4a28d870f36cf34", "dac4fbda936c2c91", "cd43cb9cfca6429c", "211c2760f64e0696", "1557a38847ee7bf7", "1be99fdf2f1602d1", "279891ae7210ecdc", "c4adbc9fb8477aa3", "7ed96aa9e45f92c9", "e0296a46d61ed530", "907850856e2216e8", "7fe821a7ccdaa943", "4571348267e388e7", "dc4191ad7cdc802b", "f354a64b7b74dd24", "ae8d21cd628518db", "c559df863baf52fc", "49b6ca9214997321", "7440069799a1af8f", "baf25ac3be555227", "f1d6799c698346e9", "e7eb00f1a58d2e56", "d7e5a49243ac7e57", "fead2026a75b8c47", "160466885ff2681a", "7a32e5deeae02bf5", "2c7dddab75b73571", "46549a8f3da997a6")),
    ParityCase("fr", "Chapelet des Sept Douleurs", "## Comment prier\n\nCommencer par un **acte de contrition**. Pour chaque douleur, annoncer le mystère, prendre un temps de méditation, puis réciter **un Notre Père et sept Je vous salue Marie**.\n\n## 1. La prophétie de Syméon\n\n**Luc 2, 25–35**\n\nSyméon reçoit l’Enfant Jésus au Temple et annonce à Marie qu’un glaive transpercera son âme. Marie accepte qu’aimer son Fils signifie aussi partager sa souffrance.\n\n## 2. La fuite en Égypte\n\n**Matthieu 2, 13–15**\n\nAvertis du danger venant d’Hérode, Marie et Joseph fuient avec l’Enfant Jésus. Marie porte le Fils de Dieu en exil et se confie au Père au milieu de la peur et de l’incertitude.\n\n## 3. La perte de l’Enfant Jésus au Temple\n\n**Luc 2, 41–50**\n\nAprès trois jours d’angoisse, Marie et Joseph retrouvent Jésus parmi les docteurs du Temple. Marie garde ses paroles dans son cœur, même lorsque sa mission demeure difficile à comprendre.\n\n## 4. Marie rencontre Jésus portant la Croix\n\n**Dévotion traditionnelle ; voir Luc 23, 27–31**\n\nSur le chemin du Calvaire, la Mère et le Fils se rencontrent dans une compassion silencieuse. Marie ne peut enlever la Croix, mais sa présence fidèle accompagne Jésus dans sa souffrance.\n\n## 5. Marie se tient au pied de la Croix\n\n**Jean 19, 25–30**\n\nMarie demeure auprès de Jésus au Calvaire. Du haut de la Croix, le Christ la confie au disciple bien-aimé et la donne pour mère à ses disciples.\n\n## 6. Marie reçoit le corps de Jésus\n\n**Dévotion traditionnelle ; voir Jean 19, 31–37**\n\nLe corps de Jésus est descendu de la Croix et déposé dans les bras de sa mère. Marie tient le Fils qu’elle avait bercé à Bethléem et offre sa douleur à Dieu.\n\n## 7. La mise au tombeau de Jésus\n\n**Jean 19, 38–42**\n\nMarie accompagne Jésus jusqu’au tombeau et reste fidèle lorsque tout espoir humain semble éteint. Sa douleur veille dans le silence qui précède Pâques.\n\n## Prières finales\n\nRéciter **trois Je vous salue Marie** en l’honneur des larmes de Notre-Dame, puis un **Notre Père**, un **Je vous salue Marie** et un **Gloire au Père** aux intentions du Saint-Père.\n\nRépéter trois fois :\n\n> Vierge très douloureuse, priez pour nous.", listOf("a453a6d015279976", "f69183a8e3f16478", "a229135630fa0d50", "0fcf66d6002c4add", "8b47302513806e8b", "14d7952ffe4d8e61", "c5af8b0061cd4961", "88555bea7a026e89", "30325b1a39ee2155", "a561d48060603499", "8df54dfea4df994c", "963b1541eaf5f124", "2aba69b521494124", "27abfcf477132692", "327b2fcf1b33f595", "640f5df3dae5bead", "89599e1c200a63d6", "278c223fb04e1f88", "a5e222dce488d0b6", "05ce0b1fa3b8a026", "31012fa02fdb81e4", "a6484baa76d1e80e", "fdcd8efbcd03f1f9", "4ace295e2586038a", "0650f8b0fba60085", "d725f3a8ed29dac6", "f24a6019d76ffbfe", "f0c6f226952c8432")),
    ParityCase("it", "Rosario dei sette dolori", "## Come pregarlo\n\nInizia con un **Atto di dolore**. Per ogni dolore, annuncia il mistero, fai una pausa di meditazione, poi recita **un Padre Nostro e sette Ave Maria**.\n\n## 1. La profezia di Simeone\n\n**Luca 2,25-35**\n\nSimeone accoglie il Bambino Gesù nel Tempio e dice a Maria che una spada le trafiggerà l'anima. Maria accetta che amare suo Figlio significhi anche condividerne la sofferenza.\n\n## 2. La fuga in Egitto\n\n**Matteo 2,13-15**\n\nAvvertiti del pericolo di Erode, Maria e Giuseppe fuggono con il piccolo Gesù. Maria porta il Figlio di Dio in esilio, confidando nel Padre in mezzo alla paura e all'incertezza.\n\n## 3. Lo smarrimento di Gesù nel Tempio\n\n**Luca 2,41-50**\n\nDopo tre giorni di angoscia, Maria e Giuseppe trovano Gesù tra i maestri nel Tempio. Maria custodisce le sue parole anche quando il cammino della sua missione è difficile da comprendere.\n\n## 4. Maria incontra Gesù che porta la croce\n\n**Devozione tradizionale; cfr. Luca 23,27-31**\n\nSulla via del Calvario, Madre e Figlio si incontrano in una silenziosa compassione. Maria non può togliere la Croce, ma la sua presenza fedele accompagna Gesù nella sofferenza.\n\n## 5. Maria sotto la croce\n\n**Giovanni 19,25-30**\n\nMaria rimane accanto a Gesù sul Calvario. Dalla Croce, Cristo la affida al discepolo amato e la dona come madre ai suoi discepoli.\n\n## 6. Maria riceve il corpo di Gesù\n\n**Devozione tradizionale; cfr. Giovanni 19,31-37**\n\nIl corpo di Gesù viene deposto dalla Croce e posto tra le braccia di sua madre. Maria stringe il Figlio che un tempo cullava a Betlemme e offre a Dio il suo dolore.\n\n## 7. La sepoltura di Gesù\n\n**Giovanni 19,38-42**\n\nMaria accompagna Gesù al sepolcro e resta fedele quando ogni speranza umana sembra spenta. Il suo dolore attende nel silenzio prima della Pasqua.\n\n## Preghiere conclusive\n\nRecita **tre Ave Maria** in onore delle lacrime della Madonna, poi un **Padre Nostro**, un'**Ave Maria** e un **Gloria al Padre** secondo le intenzioni del Santo Padre.\n\nRipeti tre volte:\n\n> Vergine addolorata, prega per noi.", listOf("480b75ba6c8b3609", "67b350084426bcd2", "1d92e1a0addc391b", "a766abded5e6e0d7", "40833eca3268a5df", "b2399bbfe72a8ca2", "44519a5fd101d903", "0ab45762c946efeb", "76a5844d1cc4c2dc", "e5539b54b8236006", "7f8309e781669b38", "d5bcd96e269ddf62", "4e86d109d9a7d12a", "e6e6264abab1323b", "212dbaadbee3d593", "dbd68cbf0542b59d", "c3b7822066d72482", "c569c7075bc15312", "1fbf7c17856e305e", "0f752ca1e85e5629", "05bdeeb7205dc1cb", "941194cdaeaadee3", "d777ee57839331dd", "d6b31104aae24e26", "9b932ff3a1c84916", "389d87fd40ae44ea", "37810bad4c3a1ab6", "af20fffdf6644abf")),
    ParityCase("es", "Rosario de los Siete Dolores", "## Cómo rezarlo\n\nComienza con un **Acto de contrición**. En cada dolor, enuncia el misterio, haz una pausa para meditar y reza **un Padrenuestro y siete Avemarías**.\n\n## 1. La profecía de Simeón\n\n**Lucas 2,25-35**\n\nSimeón recibe al Niño Jesús en el Templo y dice a María que una espada le atravesará el alma. María acepta que amar a su Hijo significará también compartir su sufrimiento.\n\n## 2. La huida a Egipto\n\n**Mateo 2,13-15**\n\nAdvertidos del peligro de Herodes, María y José huyen con el niño Jesús. María lleva al Hijo de Dios al destierro, confiando en el Padre en medio del miedo y la incertidumbre.\n\n## 3. La pérdida del Niño Jesús en el Templo\n\n**Lucas 2,41-50**\n\nTras tres días de angustia, María y José encuentran a Jesús entre los maestros del Templo. María guarda sus palabras aun cuando el camino de su misión es difícil de comprender.\n\n## 4. María encuentra a Jesús con la cruz a cuestas\n\n**Devoción tradicional; véase Lucas 23,27-31**\n\nEn el camino del Calvario, Madre e Hijo se encuentran en silenciosa compasión. María no puede quitarle la Cruz, pero su presencia fiel acompaña a Jesús en su sufrimiento.\n\n## 5. María al pie de la Cruz\n\n**Juan 19,25-30**\n\nMaría permanece junto a Jesús en el Calvario. Desde la Cruz, Cristo la confía al discípulo amado y la da como madre a sus discípulos.\n\n## 6. María recibe el cuerpo de Jesús\n\n**Devoción tradicional; véase Juan 19,31-37**\n\nEl cuerpo de Jesús es bajado de la Cruz y puesto en los brazos de su madre. María sostiene al Hijo que un día acunó en Belén y ofrece a Dios su dolor.\n\n## 7. La sepultura de Jesús\n\n**Juan 19,38-42**\n\nMaría acompaña a Jesús hasta el sepulcro y permanece fiel cuando toda esperanza humana parece apagada. Su dolor espera en el silencio antes de la Pascua.\n\n## Oraciones finales\n\nReza **tres Avemarías** en honor de las lágrimas de Nuestra Señora y después un **Padrenuestro**, un **Avemaría** y un **Gloria al Padre** por las intenciones del Santo Padre.\n\nRepite tres veces:\n\n> Virgen dolorosísima, ruega por nosotros.", listOf("fbfd66b76b1d2337", "8ec9697d58727977", "c5625edc93c2f711", "710939c55fc2bcb4", "91d263f212c15c91", "5cc79228a6d3e37e", "beb37426a30e1f62", "b48d9ed2800127aa", "3d7dde12fbf03652", "ff0336c7294a563b", "3b6806d424de0eca", "f42f6f780e0476e2", "999d5ec6316b6754", "1a66670fb63a8e28", "a1ec543cd5399816", "2587652d1db5664c", "11dd2496d35b422c", "fdea03676ea5103e", "387a30ee0488f7e4", "70c36df594c2a612", "e80f95e427274b42", "9bcb23d4e16ef2dd", "9684bc49eebfe367", "c3aef6dd80135467", "fe06113991b5b06e", "ac2fdad4c3c9cf4a", "c2c21ab2e878e1c2", "3b93129a03f1f3ce")),
    ParityCase("pt", "Rosário das Sete Dores", "## Como rezar\n\nComece com um **Ato de contrição**. Em cada dor, anuncie o mistério, faça uma pausa para meditar e reze **um Pai-Nosso e sete Ave-Marias**.\n\n## 1. A profecia de Simeão\n\n**Lucas 2,25-35**\n\nSimeão recebe o Menino Jesus no Templo e diz a Maria que uma espada lhe transpassará a alma. Maria aceita que amar o seu Filho significará também partilhar o seu sofrimento.\n\n## 2. A fuga para o Egito\n\n**Mateus 2,13-15**\n\nAvisados do perigo de Herodes, Maria e José fogem com o menino Jesus. Maria leva o Filho de Deus para o exílio, confiando no Pai em meio ao medo e à incerteza.\n\n## 3. A perda do Menino Jesus no Templo\n\n**Lucas 2,41-50**\n\nDepois de três dias de angústia, Maria e José encontram Jesus entre os doutores do Templo. Maria guarda as suas palavras, mesmo quando o caminho da sua missão é difícil de compreender.\n\n## 4. Maria encontra Jesus a caminho do Calvário\n\n**Devoção tradicional; ver Lucas 23,27-31**\n\nNo caminho do Calvário, Mãe e Filho se encontram em silenciosa compaixão. Maria não pode tirar-lhe a Cruz, mas a sua presença fiel acompanha Jesus no sofrimento.\n\n## 5. Maria aos pés da Cruz\n\n**João 19,25-30**\n\nMaria permanece junto de Jesus no Calvário. Da Cruz, Cristo a confia ao discípulo amado e a dá como mãe aos seus discípulos.\n\n## 6. Maria recebe o corpo de Jesus\n\n**Devoção tradicional; ver João 19,31-37**\n\nO corpo de Jesus é descido da Cruz e colocado nos braços de sua mãe. Maria segura o Filho que um dia embalou em Belém e oferece a Deus a sua dor.\n\n## 7. O sepultamento de Jesus\n\n**João 19,38-42**\n\nMaria acompanha Jesus até o sepulcro e permanece fiel quando toda esperança humana parece apagada. A sua dor espera no silêncio antes da Páscoa.\n\n## Orações finais\n\nReze **três Ave-Marias** em honra das lágrimas de Nossa Senhora e depois um **Pai-Nosso**, uma **Ave-Maria** e um **Glória ao Pai** pelas intenções do Santo Padre.\n\nRepita três vezes:\n\n> Virgem dolorosíssima, rogai por nós.", listOf("1f8bceb07169398f", "a57df2319a61fc7d", "2d47d137e351db0d", "64a08f9b9a25a454", "66ec8890640b8229", "401bc311022bd6f3", "371ada618ab2abac", "71d3b49df206fd73", "a82bddef99703d6b", "0ab1a103f7a55028", "132c27475b49ebe2", "c38f15f71672767f", "517455c05880ff16", "d110e006e8f58465", "2951a573af311cd8", "5845ef4cdb40fc29", "1d77ab99ec324392", "63f3ba5a94bdf471", "0c298749670dc00e", "3f81f8e442663b35", "9907b49144b3a8db", "18276a92da1c37e9", "5b96d7d242edfbad", "fc778bb33e4804b5", "a978cc6fa493bd73", "0ab9f37611b400a4", "1ce93d86dc69afc1", "52b538c2052eb222")),
    ParityCase("de", "Rosenkranz der Sieben Schmerzen", "## So wird er gebetet\n\nBeginne mit einem **Akt der Reue**. Nenne bei jedem Schmerz das Geheimnis, halte zur Betrachtung inne und bete dann **ein Vaterunser und sieben Gegrüßet seist du, Maria**.\n\n## 1. Die Weissagung Simeons\n\n**Lukas 2,25–35**\n\nSimeon empfängt das Jesuskind im Tempel und sagt Maria, dass ein Schwert ihre Seele durchdringen wird. Maria nimmt an, dass die Liebe zu ihrem Sohn auch bedeutet, sein Leiden zu teilen.\n\n## 2. Die Flucht nach Ägypten\n\n**Matthäus 2,13–15**\n\nVor der Gefahr durch Herodes gewarnt, fliehen Maria und Josef mit dem Kind Jesus. Maria trägt den Sohn Gottes ins Exil und vertraut dem Vater inmitten von Angst und Ungewissheit.\n\n## 3. Der Verlust des zwölfjährigen Jesus im Tempel\n\n**Lukas 2,41–50**\n\nNach drei angstvollen Tagen finden Maria und Josef Jesus unter den Lehrern im Tempel. Maria bewahrt seine Worte, auch wenn der Weg seiner Sendung schwer zu verstehen ist.\n\n## 4. Maria begegnet Jesus auf dem Kreuzweg\n\n**Überlieferte Andacht; vgl. Lukas 23,27–31**\n\nAuf dem Weg nach Golgota begegnen sich Mutter und Sohn in stillem Mitleiden. Maria kann ihm das Kreuz nicht abnehmen, doch ihre treue Gegenwart begleitet Jesus in seinem Leiden.\n\n## 5. Maria steht unter dem Kreuz\n\n**Johannes 19,25–30**\n\nMaria bleibt auf Golgota bei Jesus. Vom Kreuz herab vertraut Christus sie dem geliebten Jünger an und gibt sie seinen Jüngern zur Mutter.\n\n## 6. Maria empfängt den Leichnam Jesu\n\n**Überlieferte Andacht; vgl. Johannes 19,31–37**\n\nDer Leib Jesu wird vom Kreuz abgenommen und in die Arme seiner Mutter gelegt. Maria hält den Sohn, den sie einst in Betlehem wiegte, und bringt Gott ihren Schmerz dar.\n\n## 7. Die Grablegung Jesu\n\n**Johannes 19,38–42**\n\nMaria begleitet Jesus zum Grab und bleibt treu, als jede menschliche Hoffnung erloschen scheint. Ihr Schmerz wartet in der Stille vor Ostern.\n\n## Schlussgebete\n\nBete **drei Gegrüßet seist du, Maria** zu Ehren der Tränen Unserer Lieben Frau und dann ein **Vaterunser**, ein **Gegrüßet seist du, Maria** und ein **Ehre sei dem Vater** in den Anliegen des Heiligen Vaters.\n\nWiederhole dreimal:\n\n> Schmerzhafte Jungfrau, bitte für uns.", listOf("e1397e63e570edd9", "123796c987a0ea51", "16e4405c60e4c77a", "bbe2b21673da9030", "fb818447fcafa386", "eb61f97699540209", "1d7150d037fbc17a", "f822376e9053c60a", "85e4940f44bde8a1", "b33bd2dc321caf30", "f44366b1660abc21", "0ad4e1a96d0facda", "c1e21cdb0494b43b", "6bde8bb342cce70c", "06322dee43e23776", "115842b9931c9cb8", "30308b41cbfc76ed", "ed2df32c2187025d", "b34bfd738a372b25", "de5c68fe0cc00e4c", "afad8b0ef6ddfed3", "a3ed905cabec37d4", "59b3312beafe0616", "adcd725df27a6316", "9f9a901d3e186dfd", "daf04ad968fdb107", "9d3791a1bad96b70", "98c0291499948ff9")),
    ParityCase("nl", "Rozenkrans van de Zeven Smarten", "## Hoe te bidden\n\nBegin met een **Akte van berouw**. Noem bij elke smart het geheim, houd een moment van overweging en bid dan **één Onze Vader en zeven Wees gegroetjes**.\n\n## 1. De voorspelling van Simeon\n\n**Lucas 2,25-35**\n\nSimeon ontvangt het Kind Jezus in de tempel en zegt aan Maria dat een zwaard haar ziel zal doorboren. Maria aanvaardt dat de liefde voor haar Zoon ook betekent zijn lijden te delen.\n\n## 2. De vlucht naar Egypte\n\n**Matteüs 2,13-15**\n\nGewaarschuwd voor het gevaar van Herodes vluchten Maria en Jozef met het kind Jezus. Maria draagt de Zoon van God in ballingschap en vertrouwt op de Vader te midden van angst en onzekerheid.\n\n## 3. Het verlies van Jezus in de tempel\n\n**Lucas 2,41-50**\n\nNa drie angstige dagen vinden Maria en Jozef Jezus tussen de leraars in de tempel. Maria bewaart zijn woorden, ook wanneer de weg van zijn zending moeilijk te begrijpen is.\n\n## 4. Maria ontmoet Jezus op de kruisweg\n\n**Traditionele devotie; zie Lucas 23,27-31**\n\nOp de weg naar Golgota ontmoeten Moeder en Zoon elkaar in stil medelijden. Maria kan het kruis niet wegnemen, maar haar trouwe aanwezigheid vergezelt Jezus in zijn lijden.\n\n## 5. Maria staat onder het kruis\n\n**Johannes 19,25-30**\n\nMaria blijft bij Jezus op Golgota. Vanaf het kruis vertrouwt Christus haar toe aan de leerling die Hij liefhad en geeft Hij haar als moeder aan zijn leerlingen.\n\n## 6. Maria ontvangt het lichaam van Jezus\n\n**Traditionele devotie; zie Johannes 19,31-37**\n\nHet lichaam van Jezus wordt van het kruis afgenomen en in de armen van zijn moeder gelegd. Maria houdt de Zoon vast die zij eens in Betlehem wiegde en draagt haar verdriet aan God op.\n\n## 7. De graflegging van Jezus\n\n**Johannes 19,38-42**\n\nMaria vergezelt Jezus naar het graf en blijft trouw wanneer elke menselijke hoop gedoofd lijkt. Haar smart wacht in de stilte vóór Pasen.\n\n## Slotgebeden\n\nBid **drie Wees gegroetjes** ter ere van de tranen van Onze-Lieve-Vrouw en daarna één **Onze Vader**, één **Wees gegroet** en één **Eer aan de Vader** voor de intenties van de Heilige Vader.\n\nHerhaal driemaal:\n\n> Allerdroevigste Maagd, bid voor ons.", listOf("8b66ccabf6750fdc", "37c760d8144b5dba", "9b9604a475ebd15b", "2c31bf046b0d70d7", "5c6362e6812b5167", "cb8edefee1e7250e", "b1b467508c89b044", "b2e007a60d9fccaf", "a9de23710f4910f8", "109c99341bc4ef4e", "b2b22e046ef6df60", "4970bfa5552cf727", "301c1e62604e448b", "bc8afc65ba9e24df", "01f6b5bdc8858276", "09616af7ed0ab2f4", "856e912997058984", "f603079e09ac8178", "d8154e8e66eb163c", "a7de6295aa3c0ded", "c3cfa7bb1c30d214", "24896452b2d58530", "c95909603e0d3caf", "cf4ee38e81c69e94", "18222caa45607311", "f70df98335713e2b", "97109a48817b2ee7", "77bba0ee45bff526")),
    ParityCase("pl", "Różaniec Siedmiu Boleści", "## Jak się modlić\n\nRozpocznij od **Aktu żalu**. Przy każdej boleści zapowiedz tajemnicę, zatrzymaj się na rozważanie, a następnie odmów **jedno Ojcze nasz i siedem Zdrowaś Maryjo**.\n\n## 1. Proroctwo Symeona\n\n**Łk 2,25-35**\n\nSymeon przyjmuje Dzieciątko Jezus w świątyni i mówi Maryi, że miecz przeniknie Jej duszę. Maryja przyjmuje, że kochać Syna znaczy także dzielić Jego cierpienie.\n\n## 2. Ucieczka do Egiptu\n\n**Mt 2,13-15**\n\nOstrzeżeni przed zagrożeniem ze strony Heroda, Maryja i Józef uciekają z Dzieciątkiem Jezus. Maryja niesie Syna Bożego na wygnanie, ufając Ojcu pośród lęku i niepewności.\n\n## 3. Zgubienie Jezusa w świątyni\n\n**Łk 2,41-50**\n\nPo trzech dniach niepokoju Maryja i Józef odnajdują Jezusa wśród nauczycieli w świątyni. Maryja zachowuje Jego słowa, nawet gdy droga Jego misji jest trudna do zrozumienia.\n\n## 4. Maryja spotyka Jezusa niosącego krzyż\n\n**Tradycja pobożności; zob. Łk 23,27-31**\n\nNa drodze na Kalwarię Matka i Syn spotykają się w milczącym współcierpieniu. Maryja nie może zdjąć z Niego krzyża, ale Jej wierna obecność towarzyszy Jezusowi w cierpieniu.\n\n## 5. Maryja pod krzyżem\n\n**J 19,25-30**\n\nMaryja trwa przy Jezusie na Kalwarii. Z krzyża Chrystus powierza Ją umiłowanemu uczniowi i daje Ją jako Matkę swoim uczniom.\n\n## 6. Maryja przyjmuje ciało Jezusa\n\n**Tradycja pobożności; zob. J 19,31-37**\n\nCiało Jezusa zostaje zdjęte z krzyża i złożone w ramionach Matki. Maryja trzyma Syna, którego niegdyś kołysała w Betlejem, i ofiaruje Bogu swój ból.\n\n## 7. Złożenie Jezusa do grobu\n\n**J 19,38-42**\n\nMaryja towarzyszy Jezusowi aż do grobu i trwa wiernie, gdy wszelka ludzka nadzieja wydaje się zgaszona. Jej boleść czeka w ciszy przed Wielkanocą.\n\n## Modlitwy końcowe\n\nOdmów **trzy Zdrowaś Maryjo** ku czci łez Matki Bożej, a następnie jedno **Ojcze nasz**, jedno **Zdrowaś Maryjo** i jedno **Chwała Ojcu** w intencjach Ojca Świętego.\n\nPowtórz trzy razy:\n\n> Matko Bolesna, módl się za nami.", listOf("4a8caefae49b880a", "b58c4cada7dbe38a", "37df3032c2aeec1e", "161f5ce1c6223d6d", "ab7de2663b0f6ef6", "d75c998979e9d46e", "cd029023cd27b9c9", "975fc91d2d77d4e3", "956e1edbe7993833", "f5f2808448ffdb04", "e77f574ffabf39a9", "7d015bc01c79945b", "7e23f7ce6bd345ff", "10ef7eb63ee07cff", "86a0d8c1670bd73d", "1008441b84b09476", "4b6266edde886036", "2d70379d71caac22", "089697d8e0301e9e", "b7e3ef9ebcdbeb06", "27c9bb4134dc9f6b", "d779963906e1cb2c", "e69bd6884ec94601", "d55aff8b7209d5ad", "a6744c8a30068bb9", "f586e797802af6e5", "8bac01c4b3898f7a", "80a08ede82480777")),
    ParityCase("ta", "ஏழு வியாகுலச் செபமாலை", "## எப்படிச் செபிப்பது\n\n**மனத்துயர் செயலோடு** தொடங்குங்கள். ஒவ்வொரு வியாகுலத்துக்கும், அந்த மறைபொருளை அறிவித்து, தியானிக்கச் சற்று நின்று, பின்னர் **ஒரு விண்ணுலகில் இருக்கிற எங்கள் தந்தையே, ஏழு அருள் நிறைந்த மரியே** செபியுங்கள்.\n\n## 1. சிமியோனின் இறைவாக்கு\n\n**லூக்கா 2:25-35**\n\nசிமியோன் கோவிலில் குழந்தை இயேசுவைக் கையில் ஏந்தி, ஒரு வாள் மரியாவின் உள்ளத்தை ஊடுருவும் என்று சொல்கிறார். தம் மகனை அன்பு செய்வது அவரது துன்பத்தில் பங்கெடுப்பதையும் குறிக்கும் என்பதை மரியா ஏற்றுக்கொள்கிறார்.\n\n## 2. எகிப்துக்குத் தப்பியோடுதல்\n\n**மத்தேயு 2:13-15**\n\nஏரோதின் ஆபத்தைப் பற்றி எச்சரிக்கப்பட்ட மரியாவும் யோசேப்பும் குழந்தை இயேசுவோடு தப்பியோடுகின்றனர். அச்சத்துக்கும் நிச்சயமின்மைக்கும் நடுவில் தந்தையை நம்பி, மரியா இறைமகனைப் புலம்பெயர்வுக்குச் சுமந்து செல்கிறார்.\n\n## 3. கோவிலில் இயேசுவைக் காணாமல் போனது\n\n**லூக்கா 2:41-50**\n\nமூன்று நாள் கவலைக்குப் பின் மரியாவும் யோசேப்பும் கோவிலில் போதகர்கள் நடுவே இயேசுவைக் கண்டடைகின்றனர். அவரது பணியின் வழி புரிந்துகொள்ளக் கடினமாக இருந்தபோதும், மரியா அவருடைய சொற்களை உள்ளத்தில் இருத்திக்கொள்கிறார்.\n\n## 4. சிலுவை சுமக்கும் இயேசுவை மரியா சந்தித்தல்\n\n**மரபுவழி பக்தி; காண்க லூக்கா 23:27-31**\n\nகல்வாரிக்குச் செல்லும் வழியில் தாயும் மகனும் மௌனமான பரிவில் சந்திக்கின்றனர். மரியாவால் சிலுவையை அகற்ற முடியாது; ஆயினும் அவரது பிரமாணிக்கமான உடனிருப்பு இயேசுவின் துன்பத்தில் அவரோடு செல்கிறது.\n\n## 5. சிலுவையடியில் மரியா\n\n**யோவான் 19:25-30**\n\nகல்வாரியில் மரியா இயேசுவின் அருகில் நிற்கிறார். சிலுவையிலிருந்து கிறிஸ்து அவரை அன்புச் சீடரிடம் ஒப்படைத்து, தம் சீடர்களுக்கு அவரைத் தாயாகக் கொடுக்கிறார்.\n\n## 6. இயேசுவின் உடலை மரியா ஏற்றுக்கொள்ளுதல்\n\n**மரபுவழி பக்தி; காண்க யோவான் 19:31-37**\n\nஇயேசுவின் உடல் சிலுவையிலிருந்து இறக்கப்பட்டு அவருடைய தாயின் கைகளில் வைக்கப்படுகிறது. ஒருகாலத்தில் பெத்லகேமில் தாலாட்டிய மகனை மரியா தாங்கி, தம் துயரத்தைக் கடவுளுக்கு ஒப்புக்கொடுக்கிறார்.\n\n## 7. இயேசுவின் அடக்கம்\n\n**யோவான் 19:38-42**\n\nமரியா கல்லறை வரை இயேசுவோடு செல்கிறார்; மனித நம்பிக்கை எல்லாம் அணைந்துவிட்டது போலத் தோன்றும்போதும் பிரமாணிக்கமாய் இருக்கிறார். பாஸ்காவுக்கு முந்தைய அமைதியில் அவரது துயரம் காத்திருக்கிறது.\n\n## நிறைவுச் செபங்கள்\n\nஅன்னையின் கண்ணீரின் மாண்புக்காக **மூன்று அருள் நிறைந்த மரியே** செபித்து, பின்னர் திருத்தந்தையின் கருத்துகளுக்காக ஒரு **விண்ணுலகில் இருக்கிற எங்கள் தந்தையே**, ஒரு **அருள் நிறைந்த மரியே**, ஒரு **தந்தைக்கும்** செபியுங்கள்.\n\nமூன்று முறை சொல்லுங்கள்:\n\n> மிகவும் வியாகுலமுள்ள கன்னியே, எங்களுக்காக வேண்டிக்கொள்ளும்.", listOf("618d71239847fb8b", "92ce3134261c44a2", "e02fa6766430c21c", "31b661c5de5a58c9", "1eccdec44d2cb4a5", "1fcb7fc51251c453", "ef46db3e4b30fbff", "502f454c824f8dee", "760e1836d8dd05f6", "853c3766d6c3f009", "09355d807e672ede", "bf351897d90ea31d", "e6ef8205a81bfeee", "f04b541468c81af6", "2866e0f00d4a3f81", "e021f837f82b76d5", "c6d2e0ec211aea42", "019b8fa221d2ce78", "a9d96f7680c9098e", "42cc9e11c4f126aa", "c876019322edc662", "7e0473b44f96c982", "da934d233dd6f79d", "95d5c7aa40c271a0", "1c5959c12de45a1e", "c7fb7629d7b2491d", "20a123122c167a05", "3b056f2e87f8ef73")),
    ParityCase("en", "Memorare", "Remember, O most gracious Virgin Mary,\nthat never was it known that anyone who fled to thy protection,\nimplored thy help, or sought thine intercession, was left unaided.\nInspired by this confidence, I fly unto thee,\nO Virgin of virgins, my mother;\nto thee do I come, before thee I stand,\nsinful and sorrowful.\nO Mother of the Word Incarnate,\ndespise not my petitions,\nbut in thy mercy hear and answer me.\nAmen.", listOf("8c66ce44098a593a", "cb4e11c70c8998ed")),
    ParityCase("la", "Memorare", "Memorare, o piisima Virgo Maria,\nnon esse auditum a saeculo,\nquemquam ad tua currentem praesidia,\ntua implorantem auxilia, tua petentem suffragia esse derelicta.\nNos tali animati confidentia,\nad te, Virgo Virginum, Mater, currimus;\nad te venimus; coram te gementes peccatores assistimus.\nNoli, Mater Verbi, verba nostra despicere,\nsed audi propitia et exaudi.\nAmen.", listOf("1705a30abd5f6c7e", "4a076b0938f8538a")),
    ParityCase("fr", "Souvenez-vous", "Souvenez-vous ô très miséricordieuse Vierge Marie,\nqu'on n'a jamais entendu dire\nqu'aucun de ceux qui ont eu recours à votre protection,\nimploré votre assistance ou réclamé vos suffrages,\nait été abandonné.\nAnimé de cette confiance,\nô Vierge des vierges, ô ma mère,\nje viens vers vous,\net gémissant sous le poids de mes péchés,\nje me prosterne à vos pieds.\nO Mère du Verbe incarné,\nne méprisez pas mes prières,\nmais écoutez-les favorablement et daignez les exaucer.\nAmen.", listOf("d857dd01478758cc", "ff747b9416a5e3f1")),
    ParityCase("it", "Ricordati", "Ricordati, o piissima Vergine Maria,\nnon essersi mai udito al mondo\nche alcuno abbia ricorso al tuo patrocinio,\nimplorato il tuo aiuto, chiesto la tua protezione\ne sia stato abbandonato.\nAnimato da tale confidenza,\na te ricorro, o Madre, Vergine delle Vergini,\na te vengo e, peccatore contrito,\ninnanzi a te mi prostro.\nNon volere, o Madre del Verbo, disprezzare le mie preghiere,\nma ascoltami propizia ed esaudiscimi.\nAmen.", listOf("12d60dc1e7822d29", "a391157c35efef2f")),
    ParityCase("es", "Acordaos", "Acordaos, oh piadosísima Virgen María,\nque jamás se ha oído decir\nque ninguno de los que han acudido a tu protección,\nimplorando tu asistencia y reclamando tu socorro,\nhaya sido abandonado de ti.\nAnimado con esta confianza,\na ti también acudo, oh Madre, Virgen de las vírgenes,\ny aunque gimiendo bajo el peso de mis pecados,\nme atrevo a comparecer ante tu presencia soberana.\nNo deseches mis humildes súplicas, oh Madre del Verbo divino,\nantes bien, escúchalas y acógelas benignamente.\nAmén.", listOf("c374711920739fe9", "1b9982cde213c3e6")),
    ParityCase("pt", "Lembrai-vos", "Lembrai-vos, ó piíssima Virgem Maria,\nque nunca se ouviu dizer que algum daqueles que têm recorrido à vossa proteção,\nimplorado a vossa assistência e reclamado o vosso socorro,\nfosse por vós desamparado.\nAnimado eu, pois, com igual confiança,\na vós, ó Virgem entre todas singular, como a Mãe recorro,\nde vós me valho e, gemendo sob o peso dos meus pecados,\nme prostro a vossos pés.\nNão desprezeis as minhas súplicas, ó Mãe do Filho de Deus humanado,\nmas dignai-vos de as ouvir propícia e de me alcançar o que vos rogo.\nAmém.", listOf("adf487649c5f8bfe", "11977b04cec8d719")),
    ParityCase("de", "Gedenke, o gütigste Jungfrau Maria", "Gedenke, o gütigste Jungfrau Maria,\nes ist noch nie gehört worden,\ndass jemand, der zu dir seine Zuflucht nahm,\ndeinen Beistand anrief und um deine Fürbitte flehte,\nvon dir verlassen worden ist.\nVon diesem Vertrauen beseelt, nehme ich meine Zuflucht zu dir,\no Jungfrau der Jungfrauen, meine Mutter,\nzu dir komme ich, vor dir stehe ich als ein sündiger Mensch.\nO Mutter des ewigen Wortes, verschmähe nicht meine Worte,\nsondern höre sie gnädig an und erhöre mich!\nAmen.", listOf("dfed6648aaf08ec6", "e662c1d0c51a878e")),
    ParityCase("nl", "Gedenk, o allergoedertierenste Maagd Maria", "Gedenk, o allergoedertierenste Maagd Maria,\ndat het nooit gehoord is\ndat iemand die tot U zijn toevlucht nam,\nuw hulp inriep en om uw voorspraak smeekte,\ndoor U verlaten werd.\nDoor dit vertrouwen bezield,\nkom ik tot U, o Moeder, Maagd der maagden;\ntot U kom ik, en zuchtend onder de last van mijn zonden\nwerp ik mij voor U neer.\nO Moeder van het mensgeworden Woord, versmaad mijn woorden niet,\nmaar verhoor ze goedgunstig.\nAmen.", listOf("085d4a50f1cf38ff", "8e4e84302c72db98")),
    ParityCase("pl", "Pomnij, o najdobrotliwsza Panno Maryjo", "Pomnij, o najdobrotliwsza Panno Maryjo,\nże nigdy nie słyszano,\naby ktoś uciekający się do Ciebie,\nTwej pomocy wzywający, Ciebie o przyczynę prosząc,\nmiał być przez Ciebie opuszczony.\nUfnością taką ożywiony,\ndo Ciebie, o Panno nad pannami i Matko, biegnę,\ndo Ciebie przychodzę, przed Tobą jako grzesznik płaczący staję.\nO Matko Słowa, racz nie gardzić słowami moimi,\nale usłysz je łaskawie i wysłuchaj.\nAmen.", listOf("b94347277d00df4a", "22713502e1523ee0")),
    ParityCase("ta", "நினைவுகூரும், மிகவும் இரக்கமுள்ள கன்னி மரியாவே", "மிகவும் இரக்கமுள்ள கன்னி மரியாவே, நினைவுகூரும்:\nஉமது பாதுகாப்பை நாடி ஓடி வந்தவர்களிலோ,\nஉமது உதவியை மன்றாடியவர்களிலோ, உமது பரிந்துரையைத் தேடியவர்களிலோ\nஎவரும் கைவிடப்பட்டதாக ஒருபோதும் கேள்விப்பட்டதில்லை.\nஇந்த நம்பிக்கையால் தூண்டப்பட்டு,\nகன்னியருள் கன்னியே, என் தாயே, உம்மிடம் ஓடி வருகிறேன்;\nஉம்மிடம் வருகிறேன்; பாவியாகவும் துயருற்றவனாகவும் உம் முன் நிற்கிறேன்.\nமனுவுருவான வார்த்தையின் தாயே, என் மன்றாட்டுகளைப் புறக்கணியாதேயும்;\nஉமது இரக்கத்தால் அவற்றைக் கேட்டு எனக்குப் பதிலளியும்.\nஆமென்.", listOf("26705fa8cc970913", "fba0bd06a7ebaa41")),
)

internal data class ParityCase(val language: String, val title: String, val bodyMd: String, val keys: List<String>)
